import { NextResponse } from "next/server";
import { ROUTE_MANIFEST } from "../data/route-manifest.js";

/**
 * Unknown dynamic paths would otherwise render the route's static shell and
 * only discover notFound() mid-stream, which commits the response to 200. The
 * manifest is generated by scripts/build-search-index.mjs, so this allowlist
 * follows the content tree exactly.
 */
const ALLOWED = new Set([
  ...ROUTE_MANIFEST.static,
  ...ROUTE_MANIFEST.posts,
  ...ROUTE_MANIFEST.pages,
  ...ROUTE_MANIFEST.tags,
  ...(ROUTE_MANIFEST.public || []),
]);

export function proxy(request) {
  const { pathname } = request.nextUrl;
  if (ALLOWED.has(pathname)) return NextResponse.next();

  return NextResponse.rewrite(new URL("/_not-found", request.url), {
    status: 404,
  });
}

export const config = {
  // Let Next internals, static assets and API routes pass. All page-like
  // paths, including dotted names such as /llms.txt, go through the manifest
  // so unknown paths cannot become a 200 soft 404.
  matcher: ["/((?!_next/|static/|api/).*)"],
};
